// Arrays and maps, and the methods that come with them.

import flock
import ram

// ---------------------------------------------------------------- arrays

const names = ["Dolly", "Shaun", "Lambchop"]
baa names.length(), names.first(), names.last()

names.push("Timmy")
baa names

// Negative indexes count from the end.
baa names[0], names[-1]

// Slices are half-open: start included, end excluded.
baa names.slice(1, 3)

// The usual higher-order suspects.
const weights = [46.5, 52.0, 38.25, 61.0]
baa weights.map(fn(w) { return ram.round(w) })
baa weights.filter(fn(w) { return w > 45 })
baa weights.reduce(fn(total, w) { return total + w }, 0)
baa weights.sum(), ram.mean(weights), ram.median(weights)

// Sorting: natural order, or your own comparison.
baa names.sort()
baa names.sort(fn(a, b) { return a.length() - b.length() })

// `flock` covers the shapes that are awkward as methods.
baa flock.zip(names, weights)
baa flock.chunk([1, 2, 3, 4, 5], 2)
baa flock.partition([1, 2, 3, 4, 5, 6], fn(n) { return n % 2 == 0 })

// ------------------------------------------------------------------ maps

const sheep = { name: "Dolly", age: 6, woolly: true }

// Fields read with a dot or with an index.
baa sheep.name, sheep["age"]

// Missing keys read as nil; `get` takes a fallback, `expect` insists.
baa sheep.get("colour", "white")
baa sheep.has("age"), sheep.keys(), sheep.values()

sheep.field = "north"
sheep["age"] = 7
baa sheep

// Grouping is the map operation people actually reach for.
const HERD = [
    { name: "Dolly", farm: "Hill" },
    { name: "Shaun", farm: "Hill" },
    { name: "Timmy", farm: "Dale" },
]
const by_farm = flock.group_by(HERD, fn(s) { return s.farm })
for farm, members in by_farm {
    // Inside `{ ... }` you write ordinary Baa, quotes and all.
    baa "{farm}: {members.map(fn(s) { return s.name }).join(", ")}"
}

// Arrays and maps compare by value, not by identity.
baa [1, 2] == [1, 2]
baa { a: 1 } == { a: 1 }

// `clone` copies deeply; assignment shares.
const original = { flock: ["Dolly"] }
const copy = clone(original)
copy.flock.push("Shaun")
baa original.flock, copy.flock

// Errors: throwing, catching, and what a caught runtime error looks like.

// `throw` sends any value up the stack.
fn admit(pen, name) {
    if pen.length() >= 3 {
        throw "the pen is full"
    }
    pen.push(name)
    return pen.length()
}

const pen = []
try {
    for name in ["Dolly", "Shaun", "Timmy", "Shirley"] {
        baa "admitted {admit(pen, name)}"
    }
} catch problem {
    baa "could not admit: {problem}"
}

// Thrown values keep their type, so structured errors work.
fn shear(sheep) {
    if sheep.get("shorn", false) {
        throw { code: "ALREADY_SHORN", sheep: sheep.name }
    }
    sheep.shorn = true
    return sheep
}

try {
    const dolly = { name: "Dolly", shorn: true }
    shear(dolly)
} catch problem {
    baa "{problem.code}: {problem.sheep}"
}

// Runtime errors are catchable too. They arrive as a map with a stable code.
try {
    const flock = ["Dolly"]
    baa flock[7]
} catch problem {
    baa "caught {problem.code} at line {problem.line}"
    baa problem.message
}

// `finally` always runs, whether or not anything went wrong.
fn guarded(shouldFail) {
    try {
        if shouldFail {
            throw "trouble"
        }
        return "fine"
    } catch problem {
        return "handled: {problem}"
    } finally {
        baa "gate closed"
    }
}

baa guarded(false)
baa guarded(true)

// `assert` and `assert_eq` fail loudly, which is what tests are built on.
assert(pen.length() == 3, "the pen should hold three sheep")
assert_eq(pen, ["Dolly", "Shaun", "Timmy"])

baa "all good"

// FizzBuzz, because a language is not real until it can do this.
//
// `match` compares patterns structurally, so a pair of booleans works as a
// perfectly good pattern without any special destructuring syntax.

fn fizzbuzz(n) {
    return match [n % 3 == 0, n % 5 == 0] {
        [true, true] => "FizzBuzz",
        [true, false] => "Fizz",
        [false, true] => "Buzz",
        _ => to_string(n),
    }
}

for n in 1..=20 {
    baa fizzbuzz(n)
}

// Functions, defaults, rest parameters, closures and first-class values.

/// Count the sheep in a flock.
fn count_sheep(flock) {
    return flock.length()
}

// Parameters can have defaults.
fn greet(name, greeting = "Baa") {
    return "{greeting}, {name}!"
}

// `..rest` collects everything left over into an array.
fn tally(label, ..counts) {
    return "{label}: {counts.sum()}"
}

// Functions are values. This one takes another function.
fn apply_twice(f, value) {
    return f(f(value))
}

// Closures capture the scope they were declared in.
fn make_counter(start) {
    let count = start
    return fn() {
        count += 1
        return count
    }
}

// Functions are hoisted, so this call to `double` resolves fine.
baa apply_twice(double, 3)

fn double(n) {
    return n * 2
}

const FLOCK = ["Dolly", "Shaun", "Lambchop"]

baa count_sheep(FLOCK)
baa greet("Dolly")
baa greet("Shaun", "Hello")
baa tally("this week", 3, 4, 5)

const next = make_counter(10)
baa next(), next(), next()

// Anonymous functions inline.
const shout = fn(text) { return text.upper() + "!" }
baa shout("baa")

// Recursion.
fn fib(n) {
    if n < 2 {
        return n
    }
    return fib(n - 1) + fib(n - 2)
}

baa "fib(20) = {fib(20)}"

// The smallest Baa program that does something.
// Run it with: baa run examples/hello.baa

baa "Hello, flock!"

const FLOCK = ["Dolly", "Shaun", "Lambchop"]

for name in FLOCK {
    baa "Baa, {name}!"
}

baa "That is {len(FLOCK)} sheep, all present and accounted for."

// A larger program: a flock register that parses records, validates them,
// computes statistics and prints a report. It exercises most of the language
// in one place, and it is the program `baa bench` times.
//
//     baa run examples/large_program.baa

import wool
import flock
import ram
import lamb

const HEADER = "name,farm,age,weight,shorn"

const RAW = [
    "Dolly,Hill,6,46.5,true",
    "Shaun,Hill,4,52.0,false",
    "Lambchop,Dale,2,38.25,true",
    "Timmy,Dale,1,21.0,false",
    "Shirley,Hill,7,61.0,true",
    "Nuts,Meadowbank,3,44.75,false",
    "Hazel,Meadowbank,5,49.5,true",
    "Bitzer,Hill,8,58.0,false",
]

// --------------------------------------------------------------- parsing

/// Turn one CSV line into a sheep record, or throw a descriptive error.
fn parse_sheep(line, line_number) {
    const fields = line.split(",")
    if fields.length() != 5 {
        throw {
            code: "BAD_RECORD",
            line: line_number,
            detail: "expected 5 fields, found {fields.length()}",
        }
    }

    const age = fields[2].to_number()
    const weight = fields[3].to_number()
    if age == nil || weight == nil {
        throw {
            code: "BAD_NUMBER",
            line: line_number,
            detail: "age and weight must be numbers",
        }
    }

    return {
        name: fields[0],
        farm: fields[1],
        age: age,
        weight: weight,
        shorn: fields[4] == "true",
    }
}

fn parse_all(lines) {
    const register = []
    const problems = []
    for index, line in lines {
        try {
            register.push(parse_sheep(line, index + 1))
        } catch problem {
            problems.push(problem)
        }
    }
    return { register: register, problems: problems }
}

// ------------------------------------------------------------ statistics

fn stats_for(sheep) {
    const weights = sheep.map(fn(s) { return s.weight })
    const ages = sheep.map(fn(s) { return s.age })
    return {
        count: sheep.length(),
        total_weight: ram.round(weights.sum(), 2),
        mean_weight: ram.round(ram.mean(weights), 2),
        median_weight: ram.round(ram.median(weights), 2),
        oldest: ages.sort().last(),
        shorn: sheep.count(fn(s) { return s.shorn }),
    }
}

fn describe_size(count) {
    return match count {
        0 => "empty",
        1 => "a single sheep",
        2 || 3 => "a small flock",
        n if n >= 8 => "a proper flock",
        _ => "a decent flock",
    }
}

// --------------------------------------------------------------- report

fn column_widths(rows) {
    const widths = []
    for row in rows {
        for index, cell in row {
            const width = cell.length()
            if index >= widths.length() {
                widths.push(width)
            } else if width > widths[index] {
                widths[index] = width
            }
        }
    }
    return widths
}

fn render_table(rows) {
    const widths = column_widths(rows)
    const lines = []
    for row_index, row in rows {
        const cells = []
        for index, cell in row {
            cells.push(cell.pad_end(widths[index]))
        }
        lines.push(cells.join("  ").trim_end())
        if row_index == 0 {
            const rule = []
            for width in widths {
                rule.push("-".repeat(width))
            }
            lines.push(rule.join("  "))
        }
    }
    return lines.join("\n")
}

// ----------------------------------------------------------------- main

fn main() {
    baa wool.center(" FLOCK REGISTER ", 46, "=")
    baa ""

    const parsed = parse_all(RAW)
    const register = parsed.register

    if parsed.problems.length() > 0 {
        baa "Rejected {parsed.problems.length()} record(s):"
        for problem in parsed.problems {
            baa "  line {problem.line}: {problem.code}, {problem.detail}"
        }
        baa ""
    }

    // Table of every sheep, heaviest first.
    const rows = [HEADER.split(",").map(fn(h) { return h.upper() })]
    const heaviest_first = register.sort(fn(a, b) { return b.weight - a.weight })
    for sheep in heaviest_first {
        rows.push([
            sheep.name,
            sheep.farm,
            to_string(sheep.age),
            sheep.weight.to_fixed(2),
            match sheep.shorn {
                true => "yes",
                _ => "no",
            },
        ])
    }
    baa render_table(rows)
    baa ""

    // Per-farm breakdown.
    const by_farm = flock.group_by(register, fn(s) { return s.farm })
    const farms = by_farm.keys().sort()
    baa "By farm ({farms.length()} farms, {describe_size(register.length())}):"
    for farm in farms {
        const stats = stats_for(by_farm[farm])
        const name = farm.pad_end(12)
        const count = to_string(stats.count).pad_start(2)
        const mean = to_string(stats.mean_weight).pad_start(6)
        baa "  {name} {count} sheep, mean {mean}kg, {stats.shorn} shorn"
    }
    baa ""

    // Whole-flock statistics.
    const overall = stats_for(register)
    baa "Whole flock:"
    for key in overall.keys() {
        baa "  {key.pad_end(14)} {overall[key]}"
    }
    baa ""

    // Round-trip through JSON, because every real program eventually does.
    const encoded = lamb.encode({ flock: register, stats: overall }, 0)
    const decoded = lamb.decode(encoded)
    assert_eq(decoded.flock.length(), register.length(), "JSON round trip")
    baa "JSON round trip: {encoded.length()} bytes, {decoded.flock.length()} sheep recovered"

    // A closure-driven tally, for the sake of closures.
    const counter = make_tally()
    for sheep in register {
        if sheep.age >= 5 {
            counter.add(sheep.name)
        }
    }
    baa "Five years or older: {counter.names().join(", ")}"

    return 0
}

fn make_tally() {
    const names = []
    return { add: fn(name) { names.push(name) }, names: fn() { return names } }
}

main()

// Loops, ranges, and the ways out of them.

import shepherd

const FLOCK = ["Dolly", "Shaun", "Lambchop", "Timmy"]

// Iterate values.
for name in FLOCK {
    baa "Baa, {name}!"
}

// Two bindings give you the index as well.
for index, name in FLOCK {
    baa "{index}: {name}"
}

// Exclusive and inclusive ranges.
for i in 0..3 {
    baa "exclusive {i}"
}
for i in 1..=3 {
    baa "inclusive {i}"
}

// Ranges count down too.
for i in 3..0 {
    baa "countdown {i}"
}

// Strings iterate by character.
for letter in "baa" {
    baa letter
}

// Maps iterate by key, or by key and value.
const AGES = { Dolly: 6, Shaun: 4, Timmy: 1 }
for name, age in AGES {
    baa "{name} is {age}"
}

// `while`, `break` and `continue`.
let remaining = 5
while remaining > 0 {
    remaining -= 1
    if remaining == 2 {
        continue
    }
    if remaining == 0 {
        break
    }
    baa "remaining {remaining}"
}

// Nested loops: `break` leaves the innermost one.
// `shepherd.write` prints without a newline, unlike `baa`.
for row in 0..4 {
    for column in 0..4 {
        if column > row {
            break
        }
        shepherd.write("#")
    }
    baa ""
}

// Bindings, constants, and the values Baa can hold.

// `let` binds a name to a value and lets you change it later.
let sheep = 12
sheep = sheep + 1
sheep += 1
baa "sheep: {sheep}"

// `const` binds a name once. Reassigning it is a BAA103 error.
const MAX_SHEEP = 100
baa "capacity: {MAX_SHEEP}"

// The primitive types.
const name = "Dolly"
const woolly = true
const weight = 46.5
const owner = nil

baa type_of(name), type_of(woolly), type_of(weight), type_of(owner)

// Numbers are one type. Whole and fractional values live together.
baa 7 / 2, 7 % 2, 2 ** 10
baa 1_000_000, 0xFF, 0b1010, 0o17

// Strings interpolate with braces, and escape a literal brace with \{.
baa "The flock holds {sheep} of a maximum {MAX_SHEEP}."
baa "A literal brace looks like \{this\}."

// `??` supplies a fallback only when the left side is nil.
baa owner ?? "nobody"

// Strings and numbers concatenate when either side is text.
baa "sheep #" + sheep

// Comparison and logic.
baa sheep > 10 && sheep < MAX_SHEEP
baa !woolly

// Only nil and false are falsy: 0 and "" are truthy.
if 0 {
    baa "zero is truthy in Baa"
}
